load_job.code:
WORK_ITEM_CONTEXT_PREFIX = 'work_item:'
MODES = ('import', 'template', 'enrich')


def _variable(variables, key):
    entry = variables.get(key)
    if entry is None:
        return None
    if not isinstance(entry, dict):
        raise TypeError(f'shop_menu_agent: WorkItem variable {key} must be an object')
    return entry.get('value')


def _is_vision_ref(ref):
    file_id = ref.get('file_id')
    content_type = ref.get('content_type')
    if not isinstance(file_id, str) or not isinstance(content_type, str):
        return False
    return content_type.startswith('image/') or content_type == 'application/pdf'


async def run(args, state):
    context_id = state['context_id']
    if not isinstance(context_id, str) or not context_id.startswith(WORK_ITEM_CONTEXT_PREFIX):
        raise ValueError('shop_menu_agent: context_id must be work_item:<work_item_id> from the employee inbox')
    work_item_id = context_id[len(WORK_ITEM_CONTEXT_PREFIX):]
    item = await tools.work_item_get(work_item_id=work_item_id)
    variables = item['variables']
    mode = _variable(variables, 'mode')
    if mode not in MODES:
        raise ValueError(f'shop_menu_agent: unsupported WorkItem mode {mode!r}')
    shop_id = _variable(variables, 'shop_id')
    if not isinstance(shop_id, str) or shop_id == '':
        raise ValueError('shop_menu_agent: WorkItem variable shop_id is required')
    attachments = item['attachments']
    vision_files = [ref for ref in attachments if _is_vision_ref(ref)]
    attachment_file_ids = [
        ref['file_id'] for ref in attachments if isinstance(ref.get('file_id'), str)
    ]
    state['shop_job'] = {
        'work_item_id': work_item_id,
        'mode': mode,
        'shop_id': shop_id,
        'menu_name': _variable(variables, 'menu_name'),
        'brief': _variable(variables, 'brief'),
        'shop_product_ids': _variable(variables, 'shop_product_ids'),
        'attachment_file_ids': attachment_file_ids,
    }
    state['files'] = vision_files
    state['shop_attachments_text'] = '\n'.join(
        f"{index + 1}. file_id={ref['file_id']}; {ref['original_name']}; {ref['content_type']}"
        for index, ref in enumerate(vision_files)
    ) or 'изображений нет'
    state['failure_reason'] = ''
    if mode == 'import' and len(vision_files) == 0:
        state['failure_reason'] = 'Нет изображений или PDF меню во вложениях задачи.'
        state['job_route'] = 'failed'
    elif mode == 'import':
        state['job_route'] = 'import'
    else:
        state['job_route'] = 'catalog'
    return state
